import csv, json
from datetime import datetime, timezone
from collections import defaultdict

DATA = '/app/data'

def read_csv(p):
    with open(p, newline='', encoding='utf-8') as f:
        return list(csv.DictReader(f))

departments = read_csv(f'{DATA}/departments.csv')
employees = read_csv(f'{DATA}/employees.csv')
projects = read_csv(f'{DATA}/projects.csv')

# index employees by department
emp_by_dept = defaultdict(list)
for e in employees:
    e['years_of_service'] = int(e['years_of_service'])
    e['skills'] = [s.strip() for s in e['skills'].split(';') if s.strip()]
    emp_by_dept[e['department_id']].append(e)

proj_by_dept = defaultdict(list)
for p in projects:
    p['members'] = [m.strip() for m in p['member_ids'].split(';') if m.strip()]
    proj_by_dept[p['department_id']].append(p)

dept_list = []
for d in departments:
    d['budget'] = float(d['budget'])
    emps = []
    for e in emp_by_dept.get(d['id'], []):
        emps.append({
            'id': e['id'],
            'name': e['name'],
            'position': e['position'],
            'skills': e['skills'],
            'years_of_service': e['years_of_service'],
        })
    projs = []
    for p in proj_by_dept.get(d['id'], []):
        projs.append({
            'name': p['name'],
            'status': p['status'],
            'members': p['members'],
            'deadline': p['deadline'],
