    dept_list.append({
        'id': d['id'],
        'name': d['name'],
        'budget': d['budget'],
        'employees': emps,
        'projects': projs,
    })

# statistics
total_budget = sum(d['budget'] for d in dept_list)
average_budget = round(total_budget / len(dept_list), 2) if dept_list else 0
all_employees = [e for d in dept_list for e in d['employees']]
total_employees = len(all_employees)

skill_dist = defaultdict(int)
for e in all_employees:
    for s in set(e['skills']):
        skill_dist[s] += 1

dept_sizes = {d['name']: len(d['employees']) for d in dept_list}

status_dist = defaultdict(int)
for d in dept_list:
    for p in d['projects']:
        status_dist[p['status']] += 1

avg_years = round(sum(e['years_of_service'] for e in all_employees) / total_employees, 2) if total_employees else 0

out = {
    'metadata': {
        'version': '1.0.0',
        'timestamp': datetime.now(timezone.utc).astimezone().isoformat(),
        'generator': 'CSV-to-JSON Processor',
    },
    'organization': {
        'name': 'Global Organization',
        'founded': '2000-01-01',
        'departments': dept_list,
    },
    'statistics': {
        'averageDepartmentBudget': average_budget,
        'totalEmployees': total_employees,
        'skillDistribution': dict(skill_dist),
        'departmentSizes': dept_sizes,
        'projectStatusDistribution': dict(status_dist),
        'averageYearsOfService': avg_years,
    },
}

with open('/app/organization.json', 'w', encoding='utf-8') as f:
    json.dump(out, f, indent=2, ensure_ascii=False)

print('Wrote /app/organization.json')
print('Departments:', len(dept_list), 'Employees:', total_employees, 'Projects:', sum(len(d['projects']) for d in dept_list))
